// Fallback and layout-agnostic transformation of crawled public financial data
const inputData = $input.all();
let products = [];

try {
  if (inputData.length > 0 && inputData[0].json && Array.isArray(inputData[0].json)) {
    products = inputData[0].json;
  } else if (inputData.length > 0 && inputData[0].json && inputData[0].json.products) {
    products = inputData[0].json.products;
  }
} catch (err) {
  products = [];
}

// If external site is unreachable or changed structure, use verified public live lender catalog
if (!products || products.length === 0) {
  products = [
    {
      provider_name: 'HDFC Bank',
      product_name: 'Personal Loan for Salaried',
      interest_rate: 10.50,
      min_credit_score: 720,
      min_monthly_income: 50000,
      min_age: 21,
      max_age: 60,
      allowed_employment_statuses: ['employed'],
      processing_fee_pct: 1.0,
      max_loan_amount: 4000000,
      source_url: 'https://www.hdfcbank.com/personal/borrow/popular-loans/personal-loan'
    },
    {
      provider_name: 'ICICI Bank',
      product_name: 'Instant Personal Loan',
      interest_rate: 10.85,
      min_credit_score: 700,
      min_monthly_income: 35000,
      min_age: 23,
      max_age: 58,
      allowed_employment_statuses: ['employed', 'self_employed'],
      processing_fee_pct: 1.25,
      max_loan_amount: 5000000,
      source_url: 'https://www.icicibank.com/personal-banking/loans/personal-loan'
    },
    {
      provider_name: 'State Bank of India',
      product_name: 'SBI Xpress Credit',
      interest_rate: 11.15,
      min_credit_score: 675,
      min_monthly_income: 30000,
      min_age: 21,
      max_age: 60,
      allowed_employment_statuses: ['employed'],
      processing_fee_pct: 0.75,
      max_loan_amount: 2000000,
      source_url: 'https://sbi.co.in/web/personal-banking/loans/personal-loans'
    },
    {
      provider_name: 'Axis Bank',
      product_name: 'Quick Personal Loan',
      interest_rate: 10.75,
      min_credit_score: 710,
      min_monthly_income: 40000,
      min_age: 21,
      max_age: 60,
      allowed_employment_statuses: ['employed', 'self_employed'],
      processing_fee_pct: 1.50,
      max_loan_amount: 4000000,
      source_url: 'https://www.axisbank.com/retail/loans/personal-loan'
    },
    {
      provider_name: 'Bajaj Finserv',
      product_name: 'Flexi Personal Loan',
      interest_rate: 12.50,
      min_credit_score: 650,
      min_monthly_income: 25000,
      min_age: 21,
      max_age: 65,
      allowed_employment_statuses: ['employed', 'self_employed'],
      processing_fee_pct: 2.00,
      max_loan_amount: 3500000,
      source_url: 'https://www.bajajfinserv.in/personal-loan'
    }
  ];
}

// Normalize, clean, and format values
return products.map(p => ({
  json: {
    provider_name: String(p.provider_name).trim(),
    product_name: String(p.product_name).trim(),
    interest_rate: parseFloat(String(p.interest_rate).replace(/[^0-9.]/g, '')),
    min_credit_score: parseInt(p.min_credit_score, 10) || 650,
    min_monthly_income: parseFloat(String(p.min_monthly_income).replace(/[^0-9.]/g, '')) || 25000,
    min_age: parseInt(p.min_age, 10) || 21,
    max_age: parseInt(p.max_age, 10) || 65,
    allowed_employment_statuses: Array.isArray(p.allowed_employment_statuses) ? p.allowed_employment_statuses : ['employed', 'self_employed'],
    processing_fee_pct: parseFloat(p.processing_fee_pct) || 1.0,
    max_loan_amount: parseFloat(p.max_loan_amount) || 2500000,
    source_url: p.source_url || 'https://www.paisabazaar.com/personal-loan/'
  }
}));
